return ['domain'=>'acfml','plural-forms'=>'nplurals=3; plural=(n==1 ? 0 : n%10>=2 && n%10<=4 && (n%100<10 || n%100>=20) ? 1 : 2);','language'=>'pl_PL','project-id-version'=>'Advanced Custom Fields Multilingual 5.2.0','pot-creation-date'=>'2026-10-20 11:35+0000','po-revision-date'=>'2026-10-20 11:35+0000','x-generator'=>'PTC (Private Translation Cloud)','messages'=>['Advanced Custom Fields Multilingual'=>'Advanced Custom Fields Multilingual','https://wpml.org/documentation/wpml-core-and-add-on-plugins/acfml/'=>'https://wpml.org/documentation/wpml-core-and-add-on-plugins/acfml/','Adds compatibility between WPML and Advanced Custom Fields | <a href="https://wpml.org/documentation/translating-your-contents/acf/?utm_source=plugin&utm_medium=gui&utm_campaign=acfml">Documentation</a>'=>'Dodaje kompatybilność między WPML a Advanced Custom Fields | <a href="https://wpml.org/documentation/translating-your-contents/acf/?utm_source=plugin&utm_medium=gui&utm_campaign=acfml">Dokumentacja</a>','OnTheGoSystems'=>'OnTheGoSystems','http://www.onthegosystems.com/'=>'http://www.onthegosystems.com/','Displayed when editing an ACF field in a translation, showing its value in the original language; %1$s and %2$s turn the string into bold, and %3$s is the actual original value.%1$sOriginal%2$s: %3$s'=>'%1$sOryginał%2$s: %3$s','This type of ACF field will always be set to "Copy once".'=>'Ten typ pola ACF będzie zawsze ustawiony na „Kopiuj raz”.','ACF field name:'=>'Nazwa pola ACF:','ACF field type:'=>'Typ pola ACF:','Translation preferences'=>'Preferencje tłumaczenia','What to do with field\'s value when post/page is going to be translated'=>'Co zrobić z wartością pola, gdy wpis/strona ma zostać przetłumaczona','Translate (your current setting, no longer offered for this field type)'=>'Przetłumacz (obecne ustawienie, nie jest już oferowane dla tego typu pola)','Kept because it is your current setting. This value is no longer offered for this field type.'=>'Zachowano, ponieważ jest to obecne ustawienie. Ta wartość nie jest już oferowana dla tego typu pola.','Not recommended for this field type.'=>'Niezalecane dla tego typu pola.','Translated pages start without this content.'=>'Przetłumaczone strony zaczynają się bez tej treści.','Editable in other languages, and starts empty.'=>'Edytowalne w innych językach i zaczyna jako puste.','Visitors in every language always see exactly what the original shows.'=>'Odwiedzający w każdym języku zawsze widzą dokładnie to, co pokazuje oryginał.','Shown locked in other languages, so it cannot be edited there.'=>'Wyświetlane jako zablokowane w innych językach, więc nie można go tam edytować.','Starts the same as the original, then each language goes its own way.'=>'Zaczyna tak samo jak oryginał, a następnie każdy język idzie własną drogą.','Editable in every language, and permanently yours to maintain by hand.'=>'Edytowalne w każdym języku i na stałe pozostaje do ręcznego utrzymania.','Visitors see this in their own language.'=>'Odwiedzający widzą to w swoim własnym języku.','Filled by the translation and edited in the translation editor.'=>'Wypełniane przez tłumaczenie i edytowane w edytorze tłumaczeń.','Edit the field to set the translation preference.'=>'Edytuj pole, aby ustawić preferencję tłumaczenia.','ACFML is updating translation preferences for strings in Gutenberg Blocks. Keep using your site as usual. This notice will disappear when the process is done.'=>'ACFML aktualizuje preferencje tłumaczenia dla ciągów w blokach Gutenberg. Korzystaj z witryny jak zwykle. Ten komunikat zniknie po zakończeniu procesu.','ACFML is enabled but not effective. It requires WPML in order to work.'=>'ACFML jest włączone, ale nie działa. Do działania wymaga WPML.','ACFML is enabled but not effective. It requires Advanced Custom Fields or ACF PRO in order to work.'=>'ACFML jest włączone, ale nie działa. Do działania wymaga Advanced Custom Fields lub ACF PRO.','Activate Advanced Custom Fields'=>'Aktywuj Advanced Custom Fields','Install Advanced Custom Fields'=>'Zainstaluj Advanced Custom Fields','Field groups are set to "Translatable" in WPML settings, which prevents ACF fields from being translated.'=>'Grupy pól są ustawione na „Translatable” w ustawieniach WPML, co uniemożliwia tłumaczenie pól ACF.','This is almost never intended.'=>'Jest to prawie nigdy niezamierzone.','A configuration file (wpml-config.xml) controls this setting on this site, so it cannot be changed from here. Edit that file, or ask whoever maintains it to set the ACF field group post type to Not translatable.'=>'Plik konfiguracyjny (wpml-config.xml) kontroluje to ustawienie na tej witrynie, więc nie można go zmienić tutaj. Edytuj ten plik lub poproś osobę, która go utrzymuje, o ustawienie typu wpisu grupy pól ACF na „Nie tłumacz”.','Field group copies already created in other languages stay on the site. Changing this setting does not delete them.'=>'Kopie grup pól już utworzone w innych językach pozostają na stronie. Zmiana tego ustawienia ich nie usuwa.','Set field groups to Not translatable'=>'Ustaw grupy pól na „Nie tłumacz”','Why this matters'=>'Dlaczego to ma znaczenie','If any field is set to "Translatable", WPML will re-translate the %d posts using this field group.'=>'Jeśli jakiekolwiek pole jest ustawione na „Przetłumacz”, WPML ponownie przetłumaczy %d wpisy używające tej grupy pól.','Some posts using this field group have translations. Once you change the translation option, WPML needs to update the translation status of the posts. This can take up to 1 minute.'=>'Niektóre wpisy korzystające z tej grupy pól mają tłumaczenia. Po zmianie opcji tłumaczenia WPML musi zaktualizować status tłumaczenia wpisów. Może to potrwać do 1 minuty.','Some posts using this field group have translations. Once you change the translation option, WPML needs to update the translation status of the posts. This can take up to %d hours.'=>'Niektóre wpisy korzystające z tej grupy pól mają tłumaczenia. Po zmianie opcji tłumaczenia WPML musi zaktualizować status tłumaczenia wpisów. Może to potrwać do %d godzin.','Some posts using this field group have translations. Once you change the translation option, WPML needs to update the translation status of the posts. This can take up to %d minutes.'=>'Niektóre wpisy korzystające z tej grupy pól mają tłumaczenia. Po zmianie opcji tłumaczenia WPML musi zaktualizować status tłumaczenia wpisów. Może to potrwać do %d minut.','Locked by WPML so that ACF fields stay translatable. Click here to unlock and change it anyway.'=>'Zablokowane przez WPML, aby pola ACF pozostały możliwe do tłumaczenia. Kliknij tutaj, aby odblokować i mimo to zmienić.','Set translation preferences for the attached taxonomy'=>'Ustaw preferencje tłumaczenia dla powiązanej taksonomii','Set translation preferences for the attached post type'=>'Ustaw preferencje tłumaczenia dla powiązanego typu wpisu','If you want to translate your fields, go to the WPML Settings page and make the taxonomy attached to this field group translatable. '=>'Jeśli chcesz przetłumaczyć swoje pola, przejdź do strony ustawień WPML i ustaw taksonomię powiązaną z tą grupą pól jako możliwą do tłumaczenia. ','If you want to translate your fields, go to the WPML Settings page and %1$smake the post type attached to this field group translatable%2$s.'=>'Jeśli chcesz przetłumaczyć swoje pola, przejdź do strony ustawień WPML i %1$sustaw typ wpisu powiązany z tą grupą pól jako możliwy do tłumaczenia%2$s.','Expert'=>'Ekspert','Same content in every language, translated'=>'Taka sama treść w każdym języku, przetłumaczona','Each language has its own content'=>'Każdy język ma własną treść','Translate is not offered on container fields, because it replaces the value your theme reads. The fields inside carry their own preferences.'=>'Opcja „Przetłumacz” nie jest oferowana dla pól kontenerowych, ponieważ zastępuje ona wartość odczytywaną przez motyw. Pola wewnątrz mają własne preferencje.','Translate lets each language point at its own address, which an external link often needs. A link to a page on this site already points at that page in the reader\'s language, so leave it as it is.'=>'Opcja „Translate” pozwala, aby w każdym języku wskazywany był inny adres, co jest często wymagane w przypadku linków zewnętrznych. Link do strony w tej witrynie już wskazuje na tę stronę w języku czytelnika, więc pozostaw go bez zmian.','Translate sends the link text and the URL. The target keeps the value you set, and a URL you leave as it is points at the page in the reader\'s language.'=>'Opcja „Translate” przesyła tekst linku oraz adres URL. Cel zachowuje ustawioną wartość, a adres URL pozostawiony bez zmian wskazuje na stronę w języku czytelnika.','Translating an address produces one that does not exist. An e-mail address is the same in every language.'=>'Tłumaczenie adresu tworzy taki, który nie istnieje. Adres e-mail jest taki sam w każdym języku.','A color code is not language content. Translating it changes the color your visitors see.'=>'Kod koloru nie jest treścią językową. Przetłumaczenie go zmienia kolor widoczny dla odwiedzających.','The stored value is a fixed date format that your theme reads. Translating it breaks the format.'=>'Przechowywana wartość to stały format daty odczytywany przez motyw. Przetłumaczenie go psuje format.','The stored value is the choice key, not the label your visitors see. Translating it stops the key from matching your choices. Translate the labels in <b>String Translation</b> instead.'=>'Przechowywana wartość to klucz wyboru, a nie etykieta widoczna dla odwiedzających. Przetłumaczenie go sprawi, że klucz przestanie pasować do Twoich wyborów. Zamiast tego przetłumacz etykiety w <b>String Translation</b>.','This value is read by your theme or plugin code. A translated value can stop matching what the code expects.'=>'Ta wartość jest odczytywana przez kod motywu lub wtyczki. Przetłumaczona wartość może przestać pasować do tego, czego oczekuje kod.','The file decides this again on every import, so changes made elsewhere do not stick.'=>'Plik decyduje o tym ponownie przy każdym imporcie, więc zmiany wprowadzone gdzie indziej nie zostaną zachowane.','Edit %s, or remove the entry there, to manage this field on this screen.'=>'Edytuj %s lub usuń tamtejszy wpis, aby zarządzać tym polem na tym ekranie.','Edit the configuration file, or remove the entry there, to manage this field on this screen.'=>'Edytuj plik konfiguracyjny lub usuń tamtejszy wpis, aby zarządzać tym polem na tym ekranie.','That is not the value selected above. Saving this field group applies the value above.'=>'To nie jest wartość wybrana powyżej. Zapisanie tej grupy pól zastosuje wartość powyżej.','This field group is also in %s. That file re-applies these settings the next time the group is synced.'=>'Ta grupa pól znajduje się również w %s. Ten plik ponownie zastosuje te ustawienia przy następnej synchronizacji grupy.','Locked. Managed by your theme, in its wpml-config.xml file.'=>'Zablokowane. Zarządzane przez Twój motyw w pliku wpml-config.xml.','Locked. Managed by a plugin, in its wpml-config.xml file.'=>'Zablokowane. Zarządzane przez wtyczkę w pliku wpml-config.xml.','Locked. Managed by a configuration file WPML downloaded for one of your plugins or themes.'=>'Zablokowane. Zarządzane przez plik konfiguracyjny pobrany przez WPML dla jednej z Twoich wtyczek lub motywów.','Locked. Managed by the custom XML configuration saved in WPML settings.'=>'Zablokowane. Zarządzane przez niestandardową konfigurację XML zapisaną w ustawieniach WPML.','Locked. Managed by a configuration file on this site.'=>'Zablokowane. Zarządzane przez plik konfiguracyjny na tej witrynie.','Set in the field group "%s", which uses the same field name.'=>'Ustawione w grupie pól „%s”, która używa tej samej nazwy pola.','Set in the field group\'s local JSON file.'=>'Ustawione w lokalnym pliku JSON grupy pól.','Set in the field group\'s local JSON file, %s.'=>'Ustawione w lokalnym pliku JSON grupy pól, %s.','Registered with PHP by your theme or a plugin.'=>'Zarejestrowane przez PHP przez Twój motyw lub wtyczkę.','Set on the WPML Settings screen (Custom Fields Translation).'=>'Ustawione na ekranie ustawień WPML (Tłumaczenie pól niestandardowych).','Set here, on this screen.'=>'Ustawione tutaj, na tym ekranie.','Right now this field is translated, so visitors see it in their own language.'=>'Obecnie to pole jest tłumaczone, więc odwiedzający widzą je w swoim własnym języku.','Right now this field stays identical in every language.'=>'Obecnie to pole pozostaje identyczne w każdym języku.','Right now this field starts as a copy in every language, then each language keeps its own.'=>'Obecnie to pole zaczyna jako kopia w każdym języku, a następnie każdy język zachowuje własną wersję.','Right now this field stays out of translations.'=>'Obecnie to pole pozostaje poza tłumaczeniami.','Don\'t translate'=>'Nie tłumacz','Copy'=>'Kopiuj','Copy once'=>'Kopiuj raz','Translate'=>'Przetłumacz','Field groups'=>'Grupy pól','Fields'=>'Pola','Posts'=>'Wpisy','Review them one by one'=>'Przejrzyj je jeden po drugim','Apply the recommended setup to %d group'=>'Zastosuj zalecaną konfigurację do %d grupy' . "\0" . 'Zastosuj zalecaną konfigurację do wszystkich %d' . "\0" . 'Zastosuj zalecaną konfigurację do wszystkich %d','%d ACF field group is not configured for translation.'=>'%d grupa pól ACF nie jest skonfigurowana do tłumaczenia.' . "\0" . '%d grupy pól ACF nie są skonfigurowane do tłumaczenia.' . "\0" . '%d grup pól ACF nie jest skonfigurowanych do tłumaczenia.','%d post'=>'%d wpis' . "\0" . '%d wpisy' . "\0" . '%d wpisów','%1$s field, used on %2$s, would be skipped and stay in %3$s.'=>'%1$s pole używane w: %2$s zostanie pominięte i pozostanie w języku: %3$s.' . "\0" . '%1$s pola używane w: %2$s zostaną pominięte i pozostaną w języku: %3$s.' . "\0" . '%1$s pól używanych w: %2$s zostanie pominiętych i pozostanie w języku: %3$s.','%1$s field, used on %2$s, would be skipped and stay untranslated.'=>'%1$s pole używane w: %2$s zostanie pominięte i pozostanie nieprzetłumaczone.' . "\0" . '%1$s pola używane w: %2$s zostaną pominięte i pozostaną nieprzetłumaczone.' . "\0" . '%1$s pól używanych w: %2$s zostanie pominiętych i pozostanie nieprzetłumaczonych.','You are not allowed to change the translation setup of ACF field groups.'=>'Nie masz uprawnień do zmiany konfiguracji tłumaczenia grup pól ACF.','You are not allowed to change the WPML translation settings on this site.'=>'Nie masz uprawnień do zmiany ustawień tłumaczenia WPML na tej witrynie.','To change the translation options for custom fields, edit the field group "%s".'=>'Aby zmienić opcje tłumaczenia dla pól niestandardowych, edytuj grupę pól „%s”.','These fields come from ACF’s Local JSON files. To change their translation options, go to ACF → Field Groups, sync them, and then edit their settings.'=>'Te pola pochodzą z lokalnych plików JSON ACF. Aby zmienić ich opcje tłumaczenia, przejdź do ACF → Grupy pól, zsynchronizuj je, a następnie edytuj ich ustawienia.','This field and its translation setting are registered via PHP by your theme or plugin. Changes made here will override the original configuration.'=>'To pole i jego ustawienie tłumaczenia są zarejestrowane przez PHP przez Twój motyw lub wtyczkę. Zmiany wprowadzone tutaj zastąpią oryginalną konfigurację.','ACF translation setup'=>'Konfiguracja tłumaczenia ACF','Translation setup'=>'Konfiguracja tłumaczenia','You are not allowed to review the translation setup of ACF field groups.'=>'Nie masz uprawnień do przeglądania konfiguracji tłumaczenia grup pól ACF.','Field group'=>'Grupa pól','Setup'=>'Konfiguracja','Actions'=>'Działania','This site has no ACF field groups yet.'=>'Ta witryna nie ma jeszcze żadnych grup pól ACF.','Alert:'=>'Alert:','How to do that'=>'Jak to zrobić','View fields'=>'Zobacz pola','Open Dashboard'=>'Otwórz pulpit','Apply the recommended setup'=>'Zastosuj zalecaną konfigurację','Every field group stored in this site’s database already has a translation setup.'=>'Każda grupa pól zapisana w bazie danych tej witryny ma już skonfigurowane tłumaczenie.','Back to the field groups'=>'Powrót do grup pól','Every field in those groups then gets the translation preference WPML recommends for its field type. A preference that was set by hand in one of them is replaced.'=>'Każde pole w tych grupach otrzyma wtedy preferencję tłumaczenia zalecaną przez WPML dla danego typu pola. Preferencja, która została ustawiona ręcznie w jednej z nich, zostanie zastąpiona.','Field groups that come from your theme, a plugin’s code, or an acf-json file are not changed. They cannot be saved from here.'=>'Grupy pól pochodzące z Twojego motywu, kodu wtyczki lub pliku acf-json nie zostaną zmienione. Nie można ich zapisać z tego poziomu.','Cancel'=>'Anuluj','%d field group.'=>'%d grupa pól.' . "\0" . '%d grupy pól.' . "\0" . '%d grup pól.','All of them have a translation setup.'=>'Wszystkie mają skonfigurowane tłumaczenie.','%d is not configured.'=>'%d nie jest skonfigurowana.' . "\0" . '%d nie są skonfigurowane.' . "\0" . '%d nie jest skonfigurowanych.','Apply recommended setup to the %d unconfigured group'=>'Zastosuj zalecaną konfigurację do %d nieskonfigurowanej grupy' . "\0" . 'Zastosuj zalecaną konfigurację do wszystkich %d nieskonfigurowanych grup' . "\0" . 'Zastosuj zalecaną konfigurację do wszystkich %d nieskonfigurowanych grup','This sets %1$d field group to “%2$s”.'=>'To ustawia %1$d grupę pól na „%2$s”.' . "\0" . 'To ustawi %1$d grupy pól na „%2$s”.' . "\0" . 'To ustawi %1$d grup pól na „%2$s”.','%d field group is defined in code, so it cannot be configured from here.'=>'%d grupa pól jest zdefiniowana w kodzie, więc nie można jej skonfigurować tutaj.' . "\0" . '%d grupy pól są zdefiniowane w kodzie, więc nie można ich skonfigurować z tego miejsca.' . "\0" . '%d grup pól jest zdefiniowanych w kodzie, więc nie można ich skonfigurować z tego miejsca.','Not configured'=>'Nie skonfigurowano','Not configured (defined in code)'=>'Nie skonfigurowano (zdefiniowano w kodzie)','Set for each field (defined in code)'=>'Ustawione dla każdego pola (zdefiniowane w kodzie)','Set for each field in WPML Settings (defined in code)'=>'Ustawiane dla każdego pola w Ustawieniach WPML (zdefiniowano w kodzie)','%d field set manually'=>'%d pole ustawione ręcznie' . "\0" . '%d pola ustawione ręcznie' . "\0" . '%d pól ustawionych ręcznie','Nothing decides how these fields are translated. Set %s on the fields in the code that registers this group.'=>'Nic nie decyduje o tym, jak te pola są tłumaczone. Ustaw %s na polach w kodzie, który rejestruje tę grupę.','from an acf-json file'=>'z pliku acf-json','from an acf-json file that is newer than this site’s copy'=>'z pliku acf-json, który jest nowszy niż kopia na tej witrynie','from your theme or a plugin’s code'=>'z Twojego motywu lub kodu wtyczki','%d field group now uses the recommended setup.'=>'%d grupa pól korzysta teraz z zalecanej konfiguracji.' . "\0" . '%d grupy pól korzystają teraz z zalecanej konfiguracji.' . "\0" . '%d grup pól korzysta teraz z zalecanej konfiguracji.','%d field group has a newer acf-json file waiting to be synced, so that file decides its setup.'=>'%d grupa pól ma nowszy plik acf-json czekający na synchronizację, więc ten plik decyduje o jej konfiguracji.' . "\0" . '%d grupy pól mają nowszy plik acf-json oczekujący na synchronizację, więc te pliki decydują o ich konfiguracji.' . "\0" . '%d grup pól ma nowszy plik acf-json oczekujący na synchronizację, więc te pliki decydują o ich konfiguracji.','Translation Option'=>'Opcja tłumaczenia','Multilingual Setup'=>'Multilingual setup','Loading...'=>'Ładowanie...','Activate <b>String Translation</b>'=>'Aktywuj <b>string translation</b>','To translate field group names and labels, please %1$sinstall and activate WPML’s String Translation add-on%2$s.'=>'Aby przetłumaczyć nazwy i etykiety grup pól, %1$szainstaluj i aktywuj dodatek WPML String Translation%2$s.','Activate now'=>'Aktywuj teraz','Go back'=>'Wróć','Set Up <b>Field Group Translation</b>'=>'Skonfiguruj <b>tłumaczenie grup pól</b>','To translate field labels from the <b>Translation Management</b> dashboard, finish the <b>Multilingual Setup</b> and save your field group settings.'=>'Aby przetłumaczyć etykiety pól z pulpitu <b>Translation Management</b>, dokończ <b>Multilingual Setup</b> i zapisz ustawienia grupy pól.','OK'=>'OK','Translate Field Labels'=>'Przetłumacz etykiety pól','To translate field labels, use the <b>Translation Management</b> dashboard.'=>'Aby przetłumaczyć etykiety pól, użyj pulpitu <b>Translation Management</b>.','Translate in <b>Translation Management</b>'=>'Przetłumacz w <b>translation management</b>','Don’t want to translate field labels? %1$sLearn how to disable field label translation%2$s'=>'Nie chcesz tłumaczyć etykiet pól? %1$sDowiedz się, jak wyłączyć tłumaczenie etykiet pól%2$s','Field Labels Partly Translated'=>'Etykiety pól częściowo przetłumaczone','Some field labels in this group are still untranslated. To finish translating them, go to the <b>Translation Management</b> dashboard.'=>'Niektóre etykiety pól w tej grupie są nadal nieprzetłumaczone. Aby dokończyć ich tłumaczenie, przejdź do pulpitu <b>Translation Management</b>.','Fields Labels Already Translated'=>'Etykiety pól już przetłumaczone','You already translated all field labels in this group. To update any translations, go to the <b>Translation Management</b> dashboard.'=>'Wszystkie etykiety pól w tej grupie zostały już przetłumaczone. Aby zaktualizować tłumaczenia, przejdź do pulpitu <b>Translation Management</b>.','Go to <b>Translation Management</b>'=>'Przejdź do <b>translation management</b>','Select a translation option for this field group'=>'Wybierz opcję tłumaczenia dla tej grupy pól','Visitors everywhere see the same pages, in their own language. Text is translated; layout and settings stay identical.'=>'Odwiedzający wszędzie widzą te same strony w swoim własnym języku. Tekst jest tłumaczony; układ i ustawienia pozostają identyczne.','You translate in the WPML <b>Translation Editor</b>. This works with automatic translation and <b>Translate Everything</b>.'=>'Tłumaczysz w WPML <b>Translation Editor</b>. Działa to z automatycznym tłumaczeniem i funkcją <b>Translate Everything</b>.','Every language’s pages are written and maintained on their own. Fields start as a copy of the original, then go their own way.'=>'Strony w każdym języku są pisane i utrzymywane oddzielnie. Pola zaczynają jako kopia oryginału, a następnie idą własną drogą.','You edit each language in the WordPress editor. WPML does not sync them afterwards, and automatic translation does not apply.'=>'Edytujesz każdy język w edytorze WordPress. WPML nie synchronizuje ich później, a automatyczne tłumaczenie nie ma zastosowania.','If you are migrating a site, your existing field groups will use the Expert setup. This allows you to manually choose the translation option for each field in the group.'=>'Jeśli migrujesz witrynę, Twoje istniejące grupy pól będą korzystać z konfiguracji Ekspert. Pozwala to na ręczny wybór opcji tłumaczenia dla każdego pola w grupie.','This option is %1$snot recommended%2$s for new field groups.'=>'Ta opcja jest %1$sniezalecana%2$s dla nowych grup pól.','Expert setup documentation'=>'Dokumentacja konfiguracji Ekspert','Choose'=>'Wybierz','recommended for this site'=>'zalecane dla tej witryny','Change option'=>'Zmień opcję','A Much Simpler Way to Translate Your ACF Sites'=>'Znacznie prostszy sposób na tłumaczenie witryn ACF','This new release of ACFML allows you to configure multilingual sites in one-click, instead of many complex settings. Choose how to setup the translation for the fields.'=>'To nowe wydanie ACFML pozwala skonfigurować witryny wielojęzyczne jednym kliknięciem, zamiast wielu złożonych ustawień. Wybierz, jak skonfigurować tłumaczenie dla pól.','Go to WPML Settings'=>'Przejdź do ustawień WPML','Need help choosing?'=>'Potrzebujesz pomocy w wyborze?','Documentation'=>'Dokumentacja','How to translate field labels »'=>'Jak tłumaczyć etykiety pól »','This setup translates field values.'=>'Ta konfiguracja tłumaczy wartości pól.','Translate field labels and dropdown choice labels separately. Find them under ACF Field Group in the <b>Translation Dashboard</b>.'=>'Przetłumacz etykiety pól i etykiety opcji rozwijanych oddzielnie. Znajdziesz je w sekcji ACF Field Group w <b>Kokpicie tłumaczeń</b>.','Review these translation setting changes'=>'Przejrzyj te zmiany ustawień tłumaczenia','Saving this field group makes these changes:'=>'Zapisanie tej grupy pól wprowadza następujące zmiany:','%1$s: from “%2$s” to “%3$s”'=>'%1$s: z „%2$s” na „%3$s”','Switching to the field-by-field setup keeps every field\'s current setting. From here you set each field yourself.'=>'Przełączenie na konfigurację pole po polu zachowuje obecne ustawienie każdego pola. Od tego momentu ustawiasz każde pole samodzielnie.','New translations use the new settings automatically.'=>'Nowe tłumaczenia automatycznie korzystają z nowych ustawień.','Not set'=>'Nie ustawiono','No posts with translations use this field group yet, so nothing has to be sent again.'=>'Żadne wpisy z tłumaczeniami nie używają jeszcze tej grupy pól, więc nic nie musi być wysyłane ponownie.','No terms with translations use this field group yet, so nothing has to be sent again.'=>'Żadne przetłumaczone terminy nie używają jeszcze tej grupy pól, więc nic nie musi być wysyłane ponownie.','No posts or terms with translations use this field group yet, so nothing has to be sent again.'=>'Żadne wpisy ani taksonomie z tłumaczeniami nie używają jeszcze tej grupy pól, więc nic nie musi być wysyłane ponownie.','Only apply to new translations'=>'Zastosuj tylko do nowych tłumaczeń','Checking how much content this affects...'=>'Sprawdzanie, na jaką ilość treści ma to wpływ...','Save changes'=>'Zapisz zmiany','No, go back'=>'Nie, wróć','Updating them sends them for translation again, which may use translation words.'=>'Ich aktualizacja powoduje ponowne wysłanie ich do tłumaczenia, co może zużyć słowa tłumaczenia.','Updating them marks their translations as needing an update. WPML does not send them for translation. You can send them from the Translation Dashboard.'=>'Ich aktualizacja oznaczy ich tłumaczenia jako wymagające aktualizacji. WPML nie wyśle ich do tłumaczenia. Możesz je wysłać z Kokpitu tłumaczeń.','Switching the setup applies the recommended value to the %d field in this group.'=>'Zmiana konfiguracji spowoduje zastosowanie zalecanej wartości do %d pola w tej grupie.' . "\0" . 'Zmiana konfiguracji zastosuje zalecaną wartość do wszystkich %d pól w tej grupie.' . "\0" . 'Zmiana konfiguracji zastosuje zalecaną wartość do wszystkich %d pól w tej grupie.','%d post already has translations that used the old settings.'=>'%d wpis ma już tłumaczenia, które korzystały ze starych ustawień.' . "\0" . '%d wpisy mają już tłumaczenia, które używały starych ustawień.' . "\0" . '%d wpisów ma już tłumaczenia, które używały starych ustawień.','%d term already has translations that used the old settings.'=>'%d taksonomia ma już tłumaczenia, które korzystały ze starych ustawień.' . "\0" . '%d terminy mają już tłumaczenia, które używały starych ustawień.' . "\0" . '%d terminów ma już tłumaczenia, które używały starych ustawień.','%d post uses this field group.'=>'%d wpis używa tej grupy pól.' . "\0" . '%d wpisy używają tej grupy pól.' . "\0" . '%d wpisów używa tej grupy pól.','%d post is translated by hand, so WPML does not send it for translation.'=>'%d wpis jest tłumaczony ręcznie, więc WPML nie wysyła go do tłumaczenia.' . "\0" . '%d wpisy są tłumaczone ręcznie, więc WPML nie wysyła ich do tłumaczenia.' . "\0" . '%d wpisów jest tłumaczonych ręcznie, więc WPML nie wysyła ich do tłumaczenia.','Also update the %d existing post'=>'Zaktualizuj również %d istniejący wpis' . "\0" . 'Zaktualizuj także %d istniejące wpisy' . "\0" . 'Zaktualizuj także %d istniejących wpisów','Also update the %d existing term'=>'Zaktualizuj również %d istniejącą taksonomię' . "\0" . 'Zaktualizuj także %d istniejące terminy' . "\0" . 'Zaktualizuj także %d istniejących terminów','Also update the %1$d existing posts and %2$d terms'=>'Zaktualizuj również %1$d istniejących wpisów i %2$d taksonomii','Also update the %1$d existing post and %2$d terms'=>'Zaktualizuj również %1$d istniejący wpis i %2$d taksonomii','Also update the %1$d existing posts and %2$d term'=>'Zaktualizuj również %1$d istniejących wpisów i %2$d taksonomię','Also update the %1$d existing post and %2$d term'=>'Zaktualizuj również %1$d istniejący wpis i %2$d taksonomię','This field group is shown on an Options page.'=>'Ta grupa pól jest wyświetlana na stronie opcji.','That is usually site-wide content like your header, footer, or global blocks.'=>'Są to zazwyczaj treści ogólnowitrynowe, takie jak nagłówek, stopka lub bloki globalne.','To translate that content, use the %1$sWPML Translation Dashboard%2$s.'=>'Aby przetłumaczyć tę treść, użyj %1$sPulpitu tłumaczeń WPML%2$s.','The options below still decide how each field behaves: translated, copied to every language, or kept separately per language.'=>'Poniższe opcje nadal decydują o tym, jak zachowuje się każde pole: czy jest tłumaczone, kopiowane do każdego języka, czy zachowywane oddzielnie dla każdego języka.','This field group also appears on an Options page.'=>'Ta grupa pól pojawia się również na stronie opcji.','That content is translated in the %1$sWPML Translation Dashboard%2$s, and the option you choose here decides how each of its fields behaves.'=>'Ta treść jest tłumaczona w %1$sPulpicie tłumaczeń WPML%2$s, a wybrana tutaj opcja decyduje o tym, jak zachowuje się każde z jej pól.','Post Type Translation'=>'Tłumaczenie typów wpisów','Labels Translation'=>'Tłumaczenie etykiet','Taxonomy Translation'=>'Tłumaczenie taksonomii','Finish the ACF <b>Multilingual Setup</b>'=>'Dokończ <b>konfigurację wielojęzyczności</b> ACF','Before you can start translating, you need to edit each ACF Field Group to set a translation option for the fields inside it.'=>'Zanim zaczniesz tłumaczyć, musisz edytować każdą grupę pól ACF, aby ustawić preferencję tłumaczenia dla pól, które się w niej znajdują.','Read more about %1$show to translate your ACF custom fields%2$s'=>'Dowiedz się więcej o tym, %1$sjak tłumaczyć własne pola ACF%2$s','%1$sSet translation options%2$s'=>'%1$sUstaw preferencje tłumaczenia%2$s','Let\'s Start Translating!'=>'Zacznijmy tłumaczenie!','Edit each Field Group to select a translation option for the fields inside it. If you don\'t set a translation option, you will not be able to translate your fields.'=>'Edytuj każdą grupę pól, aby wybrać preferencję tłumaczenia dla pól, które się w niej znajdują. Jeśli nie ustawisz preferencji tłumaczenia, nie będzie można tłumaczyć pól.','A field in "%s" has the same name as a field in another field group. WPML stores translation preferences by field name, so two fields that share a name cannot be set differently.'=>'Pole w „%s” ma taką samą nazwę jak pole w innej grupie pól. WPML przechowuje preferencje tłumaczenia według nazwy pola, więc dwa pola o tej samej nazwie nie mogą mieć różnych ustawień.','Some fields in "%s" have the same name as fields in other field groups. WPML stores translation preferences by field name, so fields that share a name cannot be set differently.'=>'Niektóre pola w „%s” mają taką samą nazwę jak pola w innych grupach pól. WPML przechowuje preferencje tłumaczenia według nazwy pola, więc pola o tej samej nazwie nie mogą mieć różnych ustawień.','What you set here may not be what your visitors get'=>'To, co ustawisz tutaj, może nie być tym, co zobaczą odwiedzający','The field %1$s also exists in "%2$s". Rename this field to give it a translation setting of its own.'=>'Pole %1$s istnieje również w „%2$s”. Zmień nazwę tego pola, aby nadać mu własne ustawienie tłumaczenia.','See both fields'=>'Zobacz oba pola','Go to Media Translation settings'=>'Przejdź do ustawień Media Translation','This content has ACF image, gallery, or file fields, but the alt text, caption, and title of their media will not be sent for translation. To include them, turn on "Translate Media Library texts when translating content" in WPML Media Translation settings.'=>'Ta treść zawiera pola obrazu, galerii lub pliku ACF, ale tekst alternatywny, podpis i tytuł ich mediów nie zostaną wysłane do tłumaczenia. Aby je dołączyć, włącz opcję „Translate Media Library texts when translating content” w ustawieniach WPML Media Translation.','Media texts are not being translated'=>'Teksty mediów nie są tłumaczone','%1$sGo to Media Translation settings%2$s'=>'%1$sPrzejdź do ustawień Media Translation%2$s','Translate this Options page from the <b>Translation Dashboard</b>'=>'Przetłumacz tę stronę opcji z <b>Pulpitu tłumaczeń</b>','You no longer need to switch the admin language to translate options manually. Translate all your options from the %1$sTranslation Dashboard%2$s.'=>'Nie musisz już zmieniać języka administratora, aby ręcznie tłumaczyć opcje. Przetłumacz wszystkie opcje z %1$sPulpitu tłumaczeń%2$s.','Go to the Translation Dashboard'=>'Przejdź do pulpitu tłumaczeń','To change a finished translation, go to %1$sTranslation Jobs%2$s and click on the Edit Translation icon.'=>'Aby zmienić gotowe tłumaczenie, przejdź do sekcji %1$sZlecenia tłumaczenia%2$s i kliknij ikonę Edytuj tłumaczenie.','Go to Translation Jobs'=>'Przejdź do zleceń tłumaczenia','WPML blocked this save to prevent data loss. The form sent about %1$s fields, but the PHP max_input_vars limit on this server (%2$s) let fewer through. Saving now would permanently delete the fields that did not arrive, including repeater rows. Nothing was saved. Ask your host to raise max_input_vars above %1$s and save again.'=>'WPML zablokował ten zapis, aby zapobiec utracie danych. Formularz wysłał około %1$s pól, ale limit PHP max_input_vars na tym serwerze pozwolił na przesłanie tylko (%2$s). Zapisanie teraz trwale usunęłoby pola, które nie dotarły, w tym wiersze pól powtarzalnych. Nic nie zostało zapisane. Poproś hostingodawcę o zwiększenie max_input_vars powyżej %1$s i spróbuj zapisać ponownie.','Save blocked to prevent data loss'=>'Zapisywanie zablokowane, aby zapobiec utracie danych','You need to %1$stranslate this post manually%2$s because the field groups attached to it use different translation options:'=>'Musisz %1$sprzetłumaczyć ten wpis ręcznie%2$s, ponieważ dołączone do niego grupy pól używają różnych preferencji tłumaczenia:','and %d more.'=>'i %d więcej.','Show all field groups'=>'Pokaż wszystkie grupy pól','and %d more'=>'i %d więcej','You need to translate this post manually because the field groups attached to it use different translation options: %s.'=>'Musisz przetłumaczyć ten wpis ręcznie, ponieważ dołączone do niego grupy pól używają różnych preferencji tłumaczenia: %s.','Edit %s'=>'Edytuj %s','Go to documentation'=>'Przejdź do dokumentacji','This field value is copied from the default language and will be kept in sync across languages.'=>'Wartość tego pola jest kopiowana z języka domyślnego i będzie synchronizowana między językami.','Synchronise translations'=>'Synchronizuj tłumaczenia','Keep repeater and flexible sub-fields in the same order as the default language.'=>'Zachowaj pola powtarzalne i elastyczne podrzędne w tej samej kolejności, co w języku domyślnym.','ACFML Synchronise translations'=>'ACFML Synchronizuj tłumaczenia','Translate ACF Local JSON and PHP-Registered Fields'=>'Tłumacz lokalne pola ACF zarejestrowane przez JSON i PHP','ACF allows you to %1$sregister fields via PHP%2$s or %3$ssave field settings as JSON files%4$s. You can also save post types, taxonomies, or options pages settings to JSON files.'=>'ACF pozwala %1$srejestrować pola przez PHP%2$s lub %3$szapisywać ustawienia pól jako pliki JSON%4$s. Możesz również zapisywać ustawienia typów wpisów, taksonomii lub stron opcji w plikach JSON.','Configure how ACF Multilingual handles translations for these items.'=>'Skonfiguruj, jak ACF Multilingual obsługuje tłumaczenia dla tych elementów.','Sync <b>Translation Preferences</b> for Local Fields'=>'Synchronizuj <b>preferencje tłumaczenia</b> dla pól lokalnych','Don’t sync translation preferences'=>'Nie synchronizuj preferencji tłumaczenia','Sync once now'=>'Synchronizuj raz teraz','Sync on every request (may affect performance)'=>'Synchronizuj przy każdym żądaniu (może wpłynąć na wydajność)','Register Labels for Translation'=>'Zarejestruj etykiety do tłumaczenia','Scans post types, taxonomies, options pages, and field groups stored in the "acf-json" directory, then registers their labels with WPML so you can translate them.'=>'Skanuje typy wpisów, taksonomie, strony opcji i grupy pól przechowywane w katalogu „acf-json”, a następnie rejestruje ich etykiety w WPML, aby można było je przetłumaczyć.','Don’t register labels'=>'Nie rejestruj etykiet','Register labels now'=>'Zarejestruj etykiety teraz','Apply'=>'Zastosuj','The synchronization of translation preferences is disabled.'=>'Synchronizacja preferencji tłumaczenia jest wyłączona.','Translation preferences synchronized.'=>'Preferencje tłumaczenia zostały zsynchronizowane.','The synchronization of translation preferences is enabled.'=>'Synchronizacja preferencji tłumaczenia jest włączona.','%s group'=>'%s grupę' . "\0" . '%s grupy' . "\0" . '%s grup','%s post type'=>'%s typ wpisu' . "\0" . '%s typy wpisów' . "\0" . '%s typów wpisów','%s taxonomy'=>'%s taksonomię' . "\0" . '%s taksonomie' . "\0" . '%s taksonomii','%s options page'=>'%s stronę opcji' . "\0" . '%s strony opcji' . "\0" . '%s stron opcji','No local field groups, post types, taxonomies, or Options pages were found.'=>'Nie znaleziono lokalnych grup pól, typów wpisów, taksonomii ani stron opcji.','Used between elements of a two elements list and '=>' i ','Used before the last element of a three or more elements list, and '=>', i ','Successfully registered labels for %s.'=>'Pomyślnie zarejestrowano etykiety dla %s.','%1$sChange translation settings%2$s'=>'%1$sZmień ustawienia tłumaczenia%2$s','%1$sTranslate labels%2$s'=>'%1$sPrzetłumacz etykiety%2$s','Not translatable'=>'Nieprzetłumaczalne','Translatable'=>'Przetłumaczalne','only show translated items'=>'pokazuj tylko przetłumaczone elementy','use translation if available or fallback to default language'=>'użyj tłumaczenia, jeśli jest dostępne, lub wróć do języka domyślnego','This content must be translated manually due to the translation option you selected for the "%1$s" field group.'=>'Ta treść musi być tłumaczona ręcznie ze względu na opcję tłumaczenia wybraną dla grupy pól „%1$s”.']];